                break
    member = hit / max(1, len(want))
    pos = 0
    for i, r in enumerate(want):
        if i < len(got) and got[i] is not None and len(got[i]) == len(r) and all(same(fields[j][1], got[i][j], r[j]) for j in range(len(r))):
