"""Checks the file(s) the agent was asked to write. Prints a short explanation and, as the last line, {"score": x}."""
import csv, io, json, os, re, sys

SPEC = json.loads(r"""{"files": [{"must": ["(?i)total units:\\s*2960\\b", "(?i)biggest receipt:\\s*2031-03-22"], "must_not": ["[a-z]"], "path": "out/jade-annex.txt"}, {"must": ["(?i)total units:\\s*2460\\b", "(?i)biggest receipt:\\s*2031-02-20"], "must_not": ["[a-z]"], "path": "out/pumice-annex.txt"}, {"must": ["(?i)total units:\\s*2691\\b", "(?i)biggest receipt:\\s*2031-06-20"], "must_not": ["[a-z]"], "path": "out/shale-annex.txt"}, {"must": ["(?i)total units:\\s*2818\\b", "(?i)biggest receipt:\\s*2031-11-21"], "must_not": ["[a-z]"], "path": "out/quay-annex.txt"}], "kind": "files"}""")
notes = []


def norm(v):
    s = re.sub(r"\s+", " ", str(v).strip()).casefold()
    s = s.strip("`'\" ").rstrip(".")
    return s[2:] if s.startswith("./") else s


def num(v):
    if isinstance(v, bool):
        raise ValueError("bool")
    if isinstance(v, (int, float)):
        return float(v)
    s = str(v).strip().replace(",", "").replace("_", "")
    return float(s)


def same(kind, got, want, tol=0.0):
    try:
        if kind == "str":
            return norm(got) == norm(want)
        if kind == "int":
            return num(got) == int(want) and float(num(got)).is_integer()
        if kind == "num":
            return abs(num(got) - float(want)) <= tol + 1e-9
        if kind == "bool":
            if isinstance(got, bool):
                return got == want
            return norm(got) in (("true", "yes") if want else ("false", "no"))
        if kind == "oneof":
            return norm(got) in [norm(x) for x in want]
        if kind == "date":
            return str(got).strip() == want
        if kind == "none":
            return got is None or norm(got) in ("none", "null", "n/a", "")
    except (ValueError, TypeError):
        return False
    return False


def score_field(f, got):
    """returns 0..1 for one expected field"""
    kind, want = f["type"], f["value"]
    if kind in ("set", "list"):
        if not isinstance(got, list):
            return 0.0
        g = [norm(x) for x in got]
        w = [norm(x) for x in want]
        if kind == "list":
            if g == w:
                return 1.0
            jac = len(set(g) & set(w)) / max(1, len(set(g) | set(w)))
            pos = sum(1 for i in range(min(len(g), len(w))) if g[i] == w[i]) / max(1, len(w))
            return min(0.9, 0.5 * jac + 0.5 * pos)
        gs, ws = set(g), set(w)
        return len(gs & ws) / max(1, len(gs | ws))
    if kind == "map":  # str -> number/str, graded per key
        if not isinstance(got, dict):
            return 0.0
        tol = f.get("tol", 0.0)
        sub = f.get("sub", "str")
        gm = {norm(k): v for k, v in got.items()}
        hit = sum(1 for k, v in want.items() if norm(k) in gm and same(sub, gm[norm(k)], v, tol))
        extra = 0 if f.get("lenient_extra") else sum(1 for k in gm if k not in {norm(x) for x in want})
        return max(0.0, (hit - 0.5 * extra) / max(1, len(want)))
    return 1.0 if same(kind, got, want, f.get("tol", 0.0)) else 0.0


def load_json(path):
    if not os.path.exists(path):
        notes.append(f"{path}: not found")
        return None
    try:
        with open(path, encoding="utf-8") as fh:
            return json.load(fh)
    except Exception as e:  # noqa: BLE001
        notes.append(f"{path}: not valid JSON ({e})")
        return None


def check_json():
    data = load_json(SPEC["file"])
    if data is None:
        return 0.0
    if not isinstance(data, dict):
        notes.append("top level of the file must be a JSON object")
        return 0.0
    total, got_w = 0.0, 0.0
    for key, f in SPEC["fields"].items():
        w = f.get("weight", 1.0)
        total += w
        if key not in data:
            notes.append(f"missing key {key!r}")
            continue
        s = score_field(f, data[key])
        got_w += w * s
        if s < 1.0:
            notes.append(f"key {key!r}: not right ({s:.2f})")
    return got_w / total if total else 0.0


